diff --git a/runtime/orchestrator/tests/notifications/threaded-notification-e2e.test.ts b/runtime/orchestrator/tests/notifications/threaded-notification-e2e.test.ts
new file mode 100644
index 0000000..2c4af6d
--- /dev/null
+++ b/runtime/orchestrator/tests/notifications/threaded-notification-e2e.test.ts
@@ -0,0 +1,362 @@
+/**
+ * End-to-end integration-style test for threaded Slack notifications.
+ *
+ * Covers the full lifecycle using mocked Slack API and InMemoryThreadStore (fake Redis):
+ *   feature_start (top-level create)
+ *   → task thread creation (task_start)
+ *   → task status transitions (chat.update + reply)
+ *   → feature_summary_changed (chat.update on feature top-level + reply)
+ *   → feature_completed (final chat.update + reply + Redis delete)
+ *   → task_completed (final task chat.update + reply + Redis delete)
+ */
+
+import { describe, it, expect, vi, beforeEach } from "vitest";
+import { ThreadedNotificationService } from "../../src/notifications/threaded-notification-service.js";
+import { InMemoryThreadStore } from "../../src/adapters/in-memory-thread-store.js";
+import type { SlackWebApiClient } from "../../src/slack/slack-web-api-client.js";
+import type {
+  FeatureContext,
+  TaskContext,
+} from "../../src/notifications/notification.types.js";
+
+const WORKSPACE_ID = "ws-e2e";
+const FEATURE_ID = "slack-thread-notifications";
+const TASK_ID = "T1";
+
+const INITIAL_FEATURE_CTX: FeatureContext = {
+  title: "Slack Thread Notifications",
+  status: "in_implementation",
+  nextAction: "dispatch tasks",
+  totalTaskCount: 9,
+  lastUpdatedAt: "2026-05-24T00:00:00Z",
+};
+
+const INITIAL_TASK_CTX: TaskContext = {
+  title: "Slack Web API client and threaded config",
+  status: "in_progress",
+  repo: "workflow",
+  branch: "feature/slack-thread-notifications-T1",
+  lastUpdatedBy: "agent@example.com",
+};
+
+let postCallCount = 0;
+
+function makeMockSlack(): SlackWebApiClient {
+  postCallCount = 0;
+  return {
+    postMessage: vi.fn().mockImplementation(() => {
+      postCallCount++;
+      return Promise.resolve({ ts: `1716512340.00${String(postCallCount).padStart(4, "0")}`, channel: "C_E2E" });
+    }),
+    updateMessage: vi.fn().mockResolvedValue(undefined),
+  } as unknown as SlackWebApiClient;
+}
+
+describe("End-to-end: full feature + task notification lifecycle", () => {
+  let slack: SlackWebApiClient;
+  let store: InMemoryThreadStore;
+  let svc: ThreadedNotificationService;
+  const events: Array<Record<string, unknown>> = [];
+
+  beforeEach(() => {
+    slack = makeMockSlack();
+    store = new InMemoryThreadStore();
+    events.length = 0;
+    svc = new ThreadedNotificationService({
+      slack,
+      store,
+      workspaceId: WORKSPACE_ID,
+      emit: (e) => events.push(e as Record<string, unknown>),
+    });
+  });
+
+  it("feature_start creates top-level feature message and stores thread_ts", async () => {
+    await svc.postFeatureMessage(FEATURE_ID, "feature_start", INITIAL_FEATURE_CTX);
+
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    const [text, opts] = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, unknown];
+    expect(text).toContain("Feature: Slack Thread Notifications");
+    expect(text).toContain("Status: :large_green_circle: in_implementation");
+    expect(text).toContain("Next action: dispatch tasks");
+    expect(text).toContain("Tasks: 9 total");
+    expect(opts).toBeUndefined(); // top-level, no threadTs
+
+    const featureTs = await store.getFeatureThread(WORKSPACE_ID, FEATURE_ID);
+    expect(featureTs).toBeTruthy();
+
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "feature_slack_thread_created", featureId: FEATURE_ID }),
+    );
+  });
+
+  it("task_start creates top-level task message and stores task thread_ts", async () => {
+    // Set up feature thread first
+    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "feat-ts-001");
+
+    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_start", INITIAL_TASK_CTX);
+
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    const [text, opts] = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, unknown];
+    expect(text).toContain("Task: Slack Web API client and threaded config");
+    expect(text).toContain("Status: :large_green_circle: in_progress");
+    expect(text).toContain("Repo: workflow");
+    expect(text).toContain("Branch: feature/slack-thread-notifications-T1");
+    expect(text).toContain("Execution: agent@example.com");
+    expect(opts).toBeUndefined(); // top-level, no threadTs
+
+    const taskTs = await store.getTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID);
+    expect(taskTs).toBeTruthy();
+
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "task_slack_thread_created", featureId: FEATURE_ID, taskId: TASK_ID }),
+    );
+  });
+
+  it("task_status_changed calls chat.update on top-level then posts reply with thread_ts", async () => {
+    const taskTs = "task-ts-001";
+    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, taskTs);
+
+    const updatedCtx: TaskContext = {
+      ...INITIAL_TASK_CTX,
+      status: "in_review",
+      pr: { url: "https://github.com/org/workflow/pull/209", status: "open" },
+      lastUpdatedBy: "reviewer@example.com",
+      lastUpdatedAt: "2026-05-24T01:00:00Z",
+    };
+
+    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_status_changed", updatedCtx);
+
+    // chat.update on top-level
+    expect(slack.updateMessage).toHaveBeenCalledOnce();
+    const [updateTs, updateText] = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, string];
+    expect(updateTs).toBe(taskTs);
+    expect(updateText).toContain("Status: :mag: in_review");
+    expect(updateText).toContain("PR: https://github.com/org/workflow/pull/209 (open)");
+
+    // reply with thread_ts
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    const [replyText, replyOpts] = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, { threadTs: string }];
+    expect(replyText).toContain("Type: task_status_changed");
+    expect(replyOpts).toEqual({ threadTs: taskTs });
+
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "task_slack_thread_updated", featureId: FEATURE_ID, taskId: TASK_ID }),
+    );
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "task_slack_reply_posted", featureId: FEATURE_ID, taskId: TASK_ID }),
+    );
+  });
+
+  it("feature_summary_changed calls chat.update on feature top-level then posts reply", async () => {
+    const featureTs = "feat-ts-001";
+    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, featureTs);
+
+    const changedCtx: FeatureContext = {
+      ...INITIAL_FEATURE_CTX,
+      status: "blocked",
+      blockedReason: "waiting on external dependency",
+      lastUpdatedAt: "2026-05-24T02:00:00Z",
+    };
+
+    await svc.postFeatureMessage(FEATURE_ID, "feature_summary_changed", changedCtx);
+
+    // chat.update on top-level feature message
+    expect(slack.updateMessage).toHaveBeenCalledOnce();
+    const [updateTs, updateText] = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, string];
+    expect(updateTs).toBe(featureTs);
+    expect(updateText).toContain("Feature: Slack Thread Notifications");
+    expect(updateText).toContain("Status: :warning: blocked");
+    expect(updateText).toContain("Blocked: waiting on external dependency");
+
+    // reply into feature thread
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    const [replyText, replyOpts] = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, { threadTs: string }];
+    expect(replyText).toContain("Type: feature_summary_changed");
+    expect(replyOpts).toEqual({ threadTs: featureTs });
+
+    // Feature thread mapping must still exist (not deleted)
+    expect(await store.getFeatureThread(WORKSPACE_ID, FEATURE_ID)).toBe(featureTs);
+
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "feature_slack_thread_updated", featureId: FEATURE_ID }),
+    );
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "feature_slack_reply_posted", featureId: FEATURE_ID }),
+    );
+  });
+
+  it("feature_completed updates top-level, posts reply, then deletes Redis feature key", async () => {
+    const featureTs = "feat-ts-001";
+    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, featureTs);
+
+    const doneCtx: FeatureContext = {
+      ...INITIAL_FEATURE_CTX,
+      status: "done",
+      featurePr: "https://github.com/org/workflow/pull/220",
+      lastUpdatedAt: "2026-05-24T06:00:00Z",
+    };
+
+    await svc.closeFeatureThread(FEATURE_ID, doneCtx);
+
+    // chat.update
+    expect(slack.updateMessage).toHaveBeenCalledOnce();
+    const updateText = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0][1] as string;
+    expect(updateText).toContain("Status: :white_check_mark: done");
+    expect(updateText).toContain("PR: https://github.com/org/workflow/pull/220");
+
+    // final reply
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    const [replyText, replyOpts] = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, { threadTs: string }];
+    expect(replyText).toContain("Type: feature_completed");
+    expect(replyOpts).toEqual({ threadTs: featureTs });
+
+    // Redis key deleted after final message
+    expect(await store.getFeatureThread(WORKSPACE_ID, FEATURE_ID)).toBeNull();
+
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "feature_slack_thread_deleted", featureId: FEATURE_ID }),
+    );
+  });
+
+  it("task_completed updates top-level, posts final reply, then deletes Redis task key", async () => {
+    const taskTs = "task-ts-001";
+    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, taskTs);
+
+    const doneCtx: TaskContext = {
+      ...INITIAL_TASK_CTX,
+      status: "done",
+      pr: { url: "https://github.com/org/workflow/pull/209", status: "merged" },
+      lastUpdatedAt: "2026-05-24T05:00:00Z",
+    };
+
+    await svc.closeTaskThread(FEATURE_ID, TASK_ID, doneCtx);
+
+    // chat.update on top-level
+    expect(slack.updateMessage).toHaveBeenCalledOnce();
+    const updateText = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0][1] as string;
+    expect(updateText).toContain("Status: :white_check_mark: done");
+    expect(updateText).toContain("PR: https://github.com/org/workflow/pull/209 (merged)");
+
+    // final reply
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    const [replyText, replyOpts] = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0] as [string, { threadTs: string }];
+    expect(replyText).toContain("Type: task_completed");
+    expect(replyOpts).toEqual({ threadTs: taskTs });
+
+    // Redis key deleted
+    expect(await store.getTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID)).toBeNull();
+
+    expect(events).toContainEqual(
+      expect.objectContaining({ type: "task_slack_thread_deleted", featureId: FEATURE_ID, taskId: TASK_ID }),
+    );
+  });
+
+  it("full lifecycle: feature_start → task_start → task_status_changed → feature_summary_changed → task_completed → feature_completed", async () => {
+    // Step 1: feature_start
+    await svc.postFeatureMessage(FEATURE_ID, "feature_start", INITIAL_FEATURE_CTX);
+    const featureTs = await store.getFeatureThread(WORKSPACE_ID, FEATURE_ID);
+    expect(featureTs).toBeTruthy();
+    expect(slack.postMessage).toHaveBeenCalledTimes(1);
+    expect(slack.updateMessage).not.toHaveBeenCalled();
+
+    vi.clearAllMocks();
+    // Re-mock to keep returning fresh ts values
+    (slack.postMessage as ReturnType<typeof vi.fn>).mockResolvedValue({ ts: "task-ts-001", channel: "C_E2E" });
+
+    // Step 2: task_start
+    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_start", INITIAL_TASK_CTX);
+    const taskTs = await store.getTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID);
+    expect(taskTs).toBe("task-ts-001");
+    expect(slack.postMessage).toHaveBeenCalledTimes(1);
+    expect(slack.updateMessage).not.toHaveBeenCalled();
+
+    vi.clearAllMocks();
+    (slack.postMessage as ReturnType<typeof vi.fn>).mockResolvedValue({ ts: "reply-ts-001", channel: "C_E2E" });
+
+    // Step 3: task_status_changed
+    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_status_changed", {
+      ...INITIAL_TASK_CTX,
+      status: "in_review",
+    });
+    expect(slack.updateMessage).toHaveBeenCalledOnce();
+    expect((slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0][0]).toBe("task-ts-001");
+    expect(slack.postMessage).toHaveBeenCalledOnce();
+    expect((slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0][1]).toEqual({ threadTs: "task-ts-001" });
+
+    vi.clearAllMocks();
+    (slack.postMessage as ReturnType<typeof vi.fn>).mockResolvedValue({ ts: "feat-reply-001", channel: "C_E2E" });
+
+    // Step 4: feature_summary_changed
+    await svc.postFeatureMessage(FEATURE_ID, "feature_summary_changed", {
+      ...INITIAL_FEATURE_CTX,
+      status: "in_implementation",
+      nextAction: "review tasks",
+      lastUpdatedAt: "2026-05-24T03:00:00Z",
+    });
+    expect(slack.updateMessage).toHaveBeenCalledOnce();
+    expect((slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0][0]).toBe(featureTs);
+    expect(slack.postMessage).toHaveBeenCalledOnce();
